# One request brings the order, the customer and the items, with the chosen fields
query {
  order(id: 123) {
    total
    customer { name }
    items { product { name } quantity }
  }
}

// Spring for GraphQL
@Controller
class OrderGraphQlController {
    @QueryMapping
    Order order(@Argument Long id) { return service.find(id); }

    @BatchMapping                      // one call for all orders' customers: no N+1
    Map<Order, Customer> customer(List<Order> orders) { return customers.forOrders(orders); }
}

# WRONG: allowed with no limits
query { user(id: 1) { friends { friends { friends { friends { orders { items { product { name } } } } } } } } }

// RIGHT: reject queries deeper than a limit (graphql-java instrumentation)
@Bean
Instrumentation maxDepth() { return new MaxQueryDepthInstrumentation(10); }

// order.proto
syntax = "proto3";

service OrderService {
  rpc Find (FindOrderRequest) returns (Order);
  rpc FollowStatus (FindOrderRequest) returns (stream StatusUpdate);   // server streaming
}

message FindOrderRequest { int64 id = 1; }
message Order { int64 id = 1; string status = 2; int64 total_cents = 3; }   // money: never double
message StatusUpdate { string status = 1; }

// WRONG: field 3 used to be total_cents; old clients now read "discount" as the total
message Order { int64 id = 1; string status = 2; int64 discount_cents = 3; }

// RIGHT
message Order {
  reserved 3;                     // never reuse
  int64 id = 1;
  string status = 2;
  int64 total_cents = 4;
  int64 discount_cents = 5;
}
